ALTER TABLE public.posts ADD COLUMN privacy text NOT NULL DEFAULT 'public' CHECK (privacy IN ('public','friends','only_me')), ADD COLUMN background text NOT NULL DEFAULT 'none' CHECK (background IN ('none','violet','blue','green','rose')), ADD COLUMN media_items jsonb NOT NULL DEFAULT '[]'::jsonb, ADD COLUMN tagged_people jsonb NOT NULL DEFAULT '[]'::jsonb, ADD COLUMN feeling text;
ALTER TABLE public.posts ALTER COLUMN media_url SET DEFAULT '';
ALTER TABLE public.likes ADD COLUMN reaction text NOT NULL DEFAULT 'like' CHECK (reaction IN ('like','love','care','haha','wow','sad','angry'));
ALTER TABLE public.comments ADD COLUMN parent_id uuid REFERENCES public.comments(id) ON DELETE CASCADE;
CREATE TABLE public.friendships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), requester_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, recipient_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','accepted')), created_at timestamptz NOT NULL DEFAULT now(), CHECK (requester_id <> recipient_id), UNIQUE(requester_id, recipient_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.friendships TO authenticated;
GRANT ALL ON public.friendships TO service_role;
ALTER TABLE public.friendships ENABLE ROW LEVEL SECURITY;
CREATE POLICY "friends participants read" ON public.friendships FOR SELECT TO authenticated USING (auth.uid() IN (requester_id, recipient_id));
CREATE POLICY "friends request" ON public.friendships FOR INSERT TO authenticated WITH CHECK (auth.uid() = requester_id AND status = 'pending');
CREATE POLICY "friends accept" ON public.friendships FOR UPDATE TO authenticated USING (auth.uid() = recipient_id) WITH CHECK (auth.uid() = recipient_id AND status = 'accepted');
CREATE POLICY "friends remove" ON public.friendships FOR DELETE TO authenticated USING (auth.uid() IN (requester_id,recipient_id));
CREATE FUNCTION public.protect_friendship_members() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.requester_id <> OLD.requester_id OR NEW.recipient_id <> OLD.recipient_id THEN RAISE EXCEPTION 'Friendship members cannot change'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER protect_friendship_members BEFORE UPDATE ON public.friendships FOR EACH ROW EXECUTE FUNCTION public.protect_friendship_members();
ALTER POLICY "posts read" ON public.posts TO authenticated USING (auth.uid() IS NOT NULL AND (user_id = auth.uid() OR privacy = 'public' OR (privacy = 'friends' AND EXISTS (SELECT 1 FROM public.friendships f WHERE f.status='accepted' AND ((f.requester_id=auth.uid() AND f.recipient_id=posts.user_id) OR (f.recipient_id=auth.uid() AND f.requester_id=posts.user_id))))));
ALTER POLICY "comments read" ON public.comments USING (auth.uid() IS NOT NULL AND EXISTS (SELECT 1 FROM public.posts p WHERE p.id=comments.post_id));
ALTER POLICY "comments insert own" ON public.comments WITH CHECK (auth.uid()=user_id AND EXISTS (SELECT 1 FROM public.posts p WHERE p.id=comments.post_id) AND (parent_id IS NULL OR EXISTS (SELECT 1 FROM public.comments parent WHERE parent.id=comments.parent_id AND parent.post_id=comments.post_id)));
ALTER POLICY "likes read" ON public.likes USING (auth.uid() IS NOT NULL AND EXISTS (SELECT 1 FROM public.posts p WHERE p.id=likes.post_id));
ALTER POLICY "likes insert own" ON public.likes WITH CHECK (auth.uid()=user_id AND EXISTS (SELECT 1 FROM public.posts p WHERE p.id=likes.post_id));
GRANT UPDATE ON public.likes TO authenticated;
CREATE POLICY "likes update own" ON public.likes FOR UPDATE TO authenticated USING (auth.uid()=user_id) WITH CHECK (auth.uid()=user_id AND EXISTS (SELECT 1 FROM public.posts p WHERE p.id=likes.post_id));
ALTER POLICY "saves own" ON public.saves USING (auth.uid()=user_id AND EXISTS (SELECT 1 FROM public.posts p WHERE p.id=saves.post_id)) WITH CHECK (auth.uid()=user_id AND EXISTS (SELECT 1 FROM public.posts p WHERE p.id=saves.post_id));
CREATE TABLE public.shares (post_id uuid NOT NULL REFERENCES public.posts(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(post_id,user_id));
GRANT SELECT,INSERT,DELETE ON public.shares TO authenticated;
GRANT ALL ON public.shares TO service_role;
ALTER TABLE public.shares ENABLE ROW LEVEL SECURITY;
CREATE POLICY "shares read visible" ON public.shares FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL AND EXISTS (SELECT 1 FROM public.posts p WHERE p.id=shares.post_id));
CREATE POLICY "shares insert own" ON public.shares FOR INSERT TO authenticated WITH CHECK (auth.uid()=user_id AND EXISTS (SELECT 1 FROM public.posts p WHERE p.id=shares.post_id AND p.privacy <> 'only_me'));
CREATE POLICY "shares delete own" ON public.shares FOR DELETE TO authenticated USING (auth.uid()=user_id);